/// A token colour that carries both themes. `color` resolves through the
/// current `NSAppearance`, so a view drawn in light or dark (or forced with
/// `.preferredColorScheme`) picks the matching value without per-view code.
struct JidrColorPair {
    let lightRGB: UInt32
    let lightAlpha: Double
    let darkRGB: UInt32
    let darkAlpha: Double

    init(light: UInt32, dark: UInt32) {
        self.init(light: light, lightAlpha: 1, dark: dark, darkAlpha: 1)
    }

    init(light: UInt32, lightAlpha: Double, dark: UInt32, darkAlpha: Double) {
        self.lightRGB = light; self.lightAlpha = lightAlpha
        self.darkRGB = dark; self.darkAlpha = darkAlpha
    }

    var light: Color { wbTokenColor(lightRGB, lightAlpha) }
    var dark: Color { wbTokenColor(darkRGB, darkAlpha) }

    func resolved(for scheme: ColorScheme) -> Color { scheme == .dark ? dark : light }

    var color: Color {
        Color(nsColor: NSColor(name: nil) { appearance in
            let isDark = appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua
            return isDark ? wbTokenNSColor(darkRGB, darkAlpha) : wbTokenNSColor(lightRGB, lightAlpha)
        })
    }
}

private func wbTokenNSColor(_ rgb: UInt32, _ alpha: Double) -> NSColor {
    NSColor(srgbRed: CGFloat((rgb >> 16) & 0xff) / 255.0,
            green: CGFloat((rgb >> 8) & 0xff) / 255.0,
            blue: CGFloat(rgb & 0xff) / 255.0,
            alpha: CGFloat(alpha))
}

private func wbTokenColor(_ rgb: UInt32, _ alpha: Double) -> Color {
    Color(nsColor: wbTokenNSColor(rgb, alpha))
}

